using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SanctuaryChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static object Read(QuestSlice slice,string name)=>typeof(QuestSlice).GetField(name,Flags).GetValue(slice);
 static object Call(QuestSlice slice,string method,params object[] args)=>typeof(QuestSlice).GetMethod(method,Flags).Invoke(slice,args);
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var original=(SliceState)Read(slice,"state");var test=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(original));typeof(QuestSlice).GetField("state",Flags).SetValue(slice,test);var panel=(GameObject)Read(slice,"panel");var home=(GameObject)Read(slice,"sanctuaryHome");var options=(GameObject)Read(slice,"sanctuaryOptions");var confirm=(GameObject)Read(slice,"sanctuaryRestart");var book=(GameObject)Read(slice,"creationBook");var audio=(GameObject)Read(slice,"audioSettings");var held=(CarryItem[])Read(slice,"held");bool wasOpen=slice.MenuOpen;int outsideCalls=0;var outsider=new GameObject("Outside sanctuary QA",typeof(BoxCollider),typeof(SpatialTarget));outsider.GetComponent<SpatialTarget>().invoke=()=>outsideCalls++;
  SpatialTarget Find(GameObject root,string name)=>root.GetComponentsInChildren<SpatialTarget>(true).Single(t=>t.name==name);
  void Click(SpatialTarget target){Physics.SyncTransforms();var hit=target.GetComponent<Collider>();var ray=new Ray(target.transform.position-panel.transform.forward*.15f,panel.transform.forward);object[] cast={ray,.3f,default(RaycastHit)};Require((bool)Call(slice,"SanctuaryRaycast",cast),"UI ray missed "+target.name);var found=(RaycastHit)cast[2];Require(found.collider==hit,"UI ray cannot reach "+target.name);Call(slice,"SanctuaryPointer",1,true,false,found.collider,true);}
  void Layout(GameObject root){Canvas.ForceUpdateCanvases();foreach(var text in root.GetComponentsInChildren<TMPro.TMP_Text>()){text.ForceMeshUpdate();Require(text.font!=null&&!text.isTextOverflowing,"TMP caption overflow: "+text.name+" / "+text.text);Require(!text.raycastTarget,"Decorative caption blocks interaction");}Require(root.GetComponentsInChildren<Collider>(true).All(c=>c.isTrigger),"Menu introduces solid world obstacles");}
  try{
   Require(!wasOpen,"Menu must start hidden for this check");Require(slice.SetSanctuaryOpen(true)&&home.activeInHierarchy,"Home did not open");Require(!audio.activeSelf&&!book.activeSelf&&!options.activeSelf,"Overlapping pages");Layout(home);
   var pause=Find(home,"Pause");bool paused=test.paused;Call(slice,"SanctuaryPointer",1,true,false,pause.GetComponent<Collider>(),false);Require(test.paused==paused,"Untracked input activated pause");Call(slice,"SanctuaryPointer",0,true,false,pause.GetComponent<Collider>(),true);Require(test.paused==paused,"Left hand activated UI");outsider.transform.position=pause.transform.position-panel.transform.forward*.08f;outsider.transform.localScale=Vector3.one*.03f;Click(pause);Require(test.paused!=paused&&outsideCalls==0,"Scenery intercepted menu / pause did not activate");outsider.transform.position=Vector3.one*100;Call(slice,"SanctuaryPointer",1,true,true,pause.GetComponent<Collider>(),true);Require(test.paused!=paused,"Held trigger repeated action");Click(pause);Require(test.paused==paused,"Resume failed");
   Require((bool)Call(slice,"SanctuaryPointer",1,true,false,outsider.GetComponent<Collider>(),true)&&outsideCalls==0,"Menu click escaped into world");Require((bool)Call(slice,"SanctuaryPointer",1,true,false,null,true),"Off-scroll input was not consumed");var item=slice.GetComponentInChildren<CreatureHybrid>().GetComponent<CarryItem>();Require(!(bool)Call(slice,"TryGrab",1,item),"Menu allowed pickup");Require(!slice.GiveFeedback(true),"Menu allowed training");
   Click(Find(home,"Settings"));Require(options.activeInHierarchy&&!home.activeSelf,"Settings navigation failed");Layout(options);string before=JsonUtility.ToJson(test);Click(Find(options,"Begin again"));Require(confirm.activeInHierarchy&&JsonUtility.ToJson(test)==before,"Opening confirmation reset state");Layout(confirm);Click(Find(confirm,"Keep playing"));Require(options.activeInHierarchy&&JsonUtility.ToJson(test)==before,"Cancel changed season");
   Click(Find(options,"Sound"));Require(audio.activeInHierarchy&&!options.activeSelf,"Sound page navigation failed");Layout(audio);Click(Find(audio,"Back"));Require(options.activeInHierarchy&&!audio.activeSelf&&!book.activeSelf,"Sound Back opened wrong page");Click(Find(options,"Back"));Require(home.activeInHierarchy,"Home Back failed");
   Click(Find(home,"Book of\nCreation"));Require(slice.CreationBookOpen&&!home.activeSelf,"Book navigation failed");Layout(book);Click(Find(book,"Back"));Require(home.activeInHierarchy&&!book.activeSelf,"Book Back failed");
   test.paused=false;float now=test.Hybrid.time;slice.Simulate(.1f);Require(test.Hybrid.time>now,"Open menu froze simulation without explicit pause");Click(Find(home,"Save"));Require(((TMPro.TMP_Text)Read(slice,"saveCaption")).text=="Saved","No manual save acknowledgment");
   Click(Find(home,"God tools"));var palette=slice.GetComponentInChildren<GodToolPalette>();Require(!slice.MenuOpen&&palette.Open,"Menu did not transfer ownership to God Tools");slice.SetSanctuaryOpen(true);Require(!palette.Open&&!palette.Selected.HasValue,"Opening menu did not cancel tool context");slice.SetSanctuaryOpen(false);held[1]=item;Require(!slice.SetSanctuaryOpen(true)&&held[1]==item&&!slice.MenuOpen,"Menu stole held item");held[1]=null;
   Debug.Log("BWVR_SANCTUARY_PASS: hidden startup, physical tracked edge-only controls, no pickup/training/world click-through, exclusive page routing, restart cancel, pause/resume, save acknowledgment, tools handoff, held-object protection and caption bounds");
  }finally{held[1]=null;UnityEngine.Object.DestroyImmediate(outsider);slice.SetSanctuaryOpen(false);typeof(QuestSlice).GetField("state",Flags).SetValue(slice,original);if(wasOpen)slice.SetSanctuaryOpen(true);}
 }
}
}
